import React, { useState, useEffect } from 'react';
import { Card, Input, DatePicker, Button, Space, Row, Col } from 'antd';
import { SearchOutlined } from '@ant-design/icons';
import dayjs from 'dayjs';
import HybridPathInput from './HybridPathInput';
import SourcesExcludedInput from './SourcesExcludedInput';
import NormalFlightAvailabilityCalendar from './NormalFlightAvailabilityCalendar';
import './styles/NormalRouteBuilder.css';

const { RangePicker } = DatePicker;

// Storage keys
const STORAGE_KEY_PREFIX = 'normal-route-builder';
const PATH_KEY = `${STORAGE_KEY_PREFIX}-path`;
const SOURCES_EXCLUDED_KEY = `${STORAGE_KEY_PREFIX}-sources-excluded`;
const API_KEY_KEY = `${STORAGE_KEY_PREFIX}-api-key`;
const DATE_RANGE_KEY = `${STORAGE_KEY_PREFIX}-date-range`;

const NormalRouteBuilder = ({ onSearch }) => {
  const [path, setPath] = useState('');
  const [sourcesExcluded, setSourcesExcluded] = useState([]);
  const [apiKey, setApiKey] = useState('');
  const [dateRange, setDateRange] = useState(null);
  const [flightData, setFlightData] = useState(null);
  const [currentRoute, setCurrentRoute] = useState([]);

  // Load cached values on component mount
  useEffect(() => {
    // Load path
    const cachedPath = localStorage.getItem(PATH_KEY);
    if (cachedPath) setPath(cachedPath);

    // Load sources excluded
    const cachedSourcesExcluded = localStorage.getItem(SOURCES_EXCLUDED_KEY);
    if (cachedSourcesExcluded) {
      try {
        setSourcesExcluded(JSON.parse(cachedSourcesExcluded));
      } catch (e) {
        console.error('Error parsing cached sources excluded:', e);
      }
    }

    // Load API key
    const cachedApiKey = localStorage.getItem(API_KEY_KEY);
    if (cachedApiKey) setApiKey(cachedApiKey);

    // Load date range
    const cachedDateRange = localStorage.getItem(DATE_RANGE_KEY);
    if (cachedDateRange) {
      try {
        const [start, end] = JSON.parse(cachedDateRange);
        if (start && end) {
          setDateRange([dayjs(start), dayjs(end)]);
        }
      } catch (e) {
        console.error('Error parsing cached date range:', e);
      }
    }
  }, []);

  // Save path to localStorage when it changes
  useEffect(() => {
    if (path) localStorage.setItem(PATH_KEY, path);
  }, [path]);

  // Save sources excluded to localStorage when they change
  useEffect(() => {
    if (sourcesExcluded.length) {
      localStorage.setItem(SOURCES_EXCLUDED_KEY, JSON.stringify(sourcesExcluded));
    }
  }, [sourcesExcluded]);

  // Save API key to localStorage when it changes
  useEffect(() => {
    if (apiKey) localStorage.setItem(API_KEY_KEY, apiKey);
  }, [apiKey]);

  // Save date range to localStorage when it changes
  useEffect(() => {
    if (dateRange) {
      const dateRangeString = JSON.stringify([
        dateRange[0].format('YYYY-MM-DD'),
        dateRange[1].format('YYYY-MM-DD')
      ]);
      localStorage.setItem(DATE_RANGE_KEY, dateRangeString);
    }
  }, [dateRange]);

  const handleSearch = () => {
    if (!path) {
      return;
    }

    console.log('🔍 NormalRouteBuilder - Path to search:', path);
    console.log('🔍 NormalRouteBuilder - Path type:', typeof path);

    // Split path into segments for the calendar
    setCurrentRoute(path.split(/[/-]/));

    onSearch({
      path,
      sourcesExcluded,
      apiKey,
      dateRange: dateRange ? [dateRange[0].format('YYYY-MM-DD'), dateRange[1].format('YYYY-MM-DD')] : null
    });
  };

  return (
    <>
      <Card className="normal-route-builder">
        <Row gutter={[16, 16]} className="form-row">
          {/* Path Input */}
          <Col flex="10">
            <div className="form-item">
              <div className="element-label">Path:</div>
              <HybridPathInput
                value={path}
                onChange={setPath}
                placeholder="Enter path (e.g. NRT/HND-OAK/SFO-JFK/EWR)"
              />
            </div>
          </Col>

          {/* Sources Excluded */}
          <Col flex="1">
            <div className="form-item">
              <div className="element-label">Sources Excluded:</div>
              <SourcesExcludedInput
                value={sourcesExcluded}
                onChange={setSourcesExcluded}
              />
            </div>
          </Col>

          {/* API Key */}
          <Col flex="6">
            <div className="form-item">
              <div className="element-label">API Key:</div>
              <Input.Password
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                placeholder="Enter your API key"
              />
            </div>
          </Col>

          {/* Date Range */}
          <Col flex="6">
            <div className="form-item">
              <div className="element-label">Date Range:</div>
              <RangePicker
                value={dateRange}
                onChange={setDateRange}
                format="YYYY-MM-DD"
              />
            </div>
          </Col>

          {/* Search Button */}
          <Col flex="0 1 120px" className="search-button-col">
            <Button
              type="primary"
              onClick={handleSearch}
              disabled={!path}
              className="search-button"
              icon={<SearchOutlined />}
            >
              Search
            </Button>
          </Col>
        </Row>
      </Card>

      {flightData && (
        <Card style={{ marginTop: '24px' }}>
          <NormalFlightAvailabilityCalendar
            flightData={flightData}
            currentRoute={currentRoute}
            onDateRangeSelect={(range) => setDateRange([dayjs(range[0]), dayjs(range[1])])}
            selectedRange={dateRange}
          />
        </Card>
      )}
    </>
  );
};

export default NormalRouteBuilder;
